package net.fabricmc.fabric.api.event.lifecycle.v1;

import net.fabricmc.fabric.api.event.Event;
import net.fabricmc.fabric.api.event.EventFactory;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.EquipmentSlot;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.item.ItemStack;

/** Fabric API: entities appearing/disappearing in server worlds (Omniloader stand-in; generated by tools/gen-fabric-events.py). */
public final class ServerEntityEvents {
    private ServerEntityEvents() {}

    public static final Event<Load> ENTITY_LOAD = EventFactory.createArrayBacked(Load.class, ls -> (entity, world) -> { for (Load l : ls) l.onLoad(entity, world); });
    public static final Event<Unload> ENTITY_UNLOAD = EventFactory.createArrayBacked(Unload.class, ls -> (entity, world) -> { for (Unload l : ls) l.onUnload(entity, world); });
    public static final Event<EquipmentChange> EQUIPMENT_CHANGE = EventFactory.createArrayBacked(EquipmentChange.class, ls -> (livingEntity, equipmentSlot, previousStack, currentStack) -> { for (EquipmentChange l : ls) l.onChange(livingEntity, equipmentSlot, previousStack, currentStack); });

    @FunctionalInterface public interface Load { void onLoad(Entity entity, ServerLevel world); }
    @FunctionalInterface public interface Unload { void onUnload(Entity entity, ServerLevel world); }
    @FunctionalInterface public interface EquipmentChange { void onChange(LivingEntity livingEntity, EquipmentSlot equipmentSlot, ItemStack previousStack, ItemStack currentStack); }
}
